from pybricks.hubs import PrimeHub
from pybricks.parameters import Color, Direction, Port
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase

from Biocentric_Architecture_from_daniel import run_orange_mission
from Tangled_and_Reasearch_Platform45_45 import run_white_mission
from drone import run_blue_mission
from keystone_species import run_green_mission

# Set up.
cecmfe = 0
hub = PrimeHub()
Right_drive = Motor(Port.F, Direction.CLOCKWISE)
Left_drive = Motor(Port.B, Direction.COUNTERCLOCKWISE)
right_attachment = Motor(Port.E, Direction.CLOCKWISE)
left_attachment = Motor(Port.C, Direction.COUNTERCLOCKWISE)
drive_base = DriveBase(Left_drive, Right_drive, 62.4, 90)
color_sensor_BOTTOM = ColorSensor(Port.A)
color_sensor = ColorSensor(Port.D)


# The main program starts here.
if color_sensor.color() == Color.WHITE:
    hub.display.char('W')
    run_white_mission(drive_base, Left_drive, Right_drive, left_attachment, right_attachment, color_sensor_BOTTOM, cecmfe)
elif color_sensor.color() == Color.GREEN:
    hub.display.char('G')
    run_green_mission(drive_base, Left_drive, Right_drive, left_attachment, right_attachment)
elif color_sensor.color() == Color.BLUE:
    hub.display.char('B')
    run_blue_mission(drive_base, Left_drive, Right_drive, left_attachment, right_attachment)
elif color_sensor.color() == Color.RED:
    hub.display.char('O')
    run_orange_mission(drive_base, Left_drive, Right_drive, left_attachment, right_attachment)
else:
    print('I see', color_sensor.color())
